var sumOfUnique = function(nums) {
    const freq = new Map();
    for (const x of nums) {
        freq.set(x, (freq.get(x) || 0) + 1);
    }
    let ans = 0;
    for (const [x, count] of freq) {
        if (count === 1) ans += x;
    }
    return ans;
};
